# ── 演示用数据结构 ─────────────────────────────────────────

class Priority(Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


@dataclass
class TicketAnalysis:
    """工单分析结果。"""
    category: str
    priority: str
    summary: str
    suggested_actions: list[str] = field(default_factory=list)
    confidence: float = 0.9


# ═══════════════════════════════════════════════════════════
# Demo 1: JSON Schema 生成 + 验证
# ═══════════════════════════════════════════════════════════

def demo_schema():
    print("▶ 1. JSON Schema 生成 + 验证")
    print("─" * 60)

    # 从 dataclass 生成
    schema = SchemaGenerator.from_dataclass(TicketAnalysis)
    print("  从 dataclass 生成 Schema:")
    print(f"    {json.dumps(schema, indent=4, ensure_ascii=False)[:300]}...")

    # 验证正确数据
    validator = SchemaValidator(schema)
    good_data = {
        "category": "技术支持",
        "priority": "high",
        "summary": "用户无法登录系统",
        "suggested_actions": ["检查密码", "重置账号"],
        "confidence": 0.85,
    }
    errors = validator.validate(good_data)
    print(f"\n  验证正确数据: {'✅ 通过' if not errors else f'❌ {errors}'}")

    # 验证错误数据
    bad_data = {
        "category": "技术支持",
        # 缺少 priority, summary
        "confidence": "很高",  # 类型错误
        "extra_field": True,   # 额外字段
    }
    errors = validator.validate(bad_data)
    print(f"  验证错误数据: ❌")
    for e in errors:
        print(f"    - {e}")

    # 从简单 dict 生成
    simple_schema = SchemaGenerator.from_dict({"name": "string", "age": "integer", "active": "boolean"})
    print(f"\n  从 dict 生成: {json.dumps(simple_schema, ensure_ascii=False)}")


