# Demo 2: JSON 修复
# ═══════════════════════════════════════════════════════════

def demo_json_repair():
    print(f"\n\n▶ 2. JSON 修复 — 处理 LLM 常见格式错误")
    print("─" * 60)

    broken_outputs = [
        ("尾部逗号", '{"name": "张三", "age": 25,}'),
        ("单引号", "{'name': '李四', 'age': 30}"),
        ("代码块包裹", '```json\n{"result": "ok"}\n```'),
        ("无引号 key", '{name: "王五", age: 28}'),
        ("Python 布尔", '{"active": True, "deleted": False, "data": None}'),
        ("混合错误", "```\n{name: '赵六', active: True, tags: ['vip',],}\n```"),
    ]

    for desc, raw in broken_outputs:
        data, status = JSONRepair.safe_parse(raw)
        icon = "✅" if data else "❌"
        print(f"  {icon} {desc:12s} → {json.dumps(data, ensure_ascii=False) if data else status}")


