# Demo 3: Function Calling 流程
# ═══════════════════════════════════════════════════════════

def demo_function_calling():
    print(f"\n\n▶ 3. Function Calling 完整流程")
    print("─" * 60)

    # 注册工具
    registry = ToolRegistry()

    def get_weather(city: str, unit: str = "celsius") -> dict:
        """获取指定城市的天气信息。"""
        data = {"上海": 32, "北京": 28, "深圳": 35}
        return {"city": city, "temp": data.get(city, 20), "unit": unit, "condition": "晴"}

    def search_order(order_id: str) -> dict:
        """查询订单详情。"""
        return {"order_id": order_id, "status": "已发货", "amount": 299.0}

    registry.register(get_weather, "获取城市天气",
                      {"city": "城市名称", "unit": "温度单位 (celsius/fahrenheit)"})
    registry.register(search_order, "查询订单信息",
                      {"order_id": "订单编号"})

    # 展示生成的 OpenAI tools 格式
    tools = registry.to_openai_tools()
    print("  注册的工具 (OpenAI 格式):")
    for t in tools:
        print(f"    {t['function']['name']}: {t['function']['description']}")
        print(f"      params: {list(t['function']['parameters']['properties'].keys())}")

    # 模拟完整流程
    sim = FunctionCallingSimulator(registry)
    tests = [
        ("查一下上海的 get_weather", {"city": "上海"}),
        ("帮我 search_order ORD-001", {"order_id": "ORD-001"}),
        ("你好，今天天气怎么样", None),  # 不触发工具
    ]

    for user_msg, args in tests:
        result = sim.run(user_msg, tool_args=args)
        print(f"\n  用户: {user_msg}")
        if result["tool_called"]:
            print(f"    → 工具: {result['tool_called']}({result['tool_args']})")
            print(f"    → 结果: {result['tool_result']}")
        else:
            print(f"    → 未调用工具 (直接回答)")
        print(f"    → Messages: {result['messages_count']} 条")


# ═══════════════════════════════════════════════════════════
# Demo 4: Dataclass 解析 + 重试修复
# ═══════════════════════════════════════════════════════════

def demo_parsing_retry():
    print(f"\n\n▶ 4. Dataclass 解析 + 重试修复")
    print("─" * 60)

    parser = DataclassParser(TicketAnalysis)

    # 正确输出
    good = '{"category": "技术支持", "priority": "high", "summary": "登录失败", "suggested_actions": ["重置密码"], "confidence": 0.9}'
    result, errors = parser.parse(good)
    print(f"  正确输出: {'✅' if result else '❌'} {result}")

    # 格式错误但可修复
    broken = "```json\n{category: '网络问题', priority: 'medium', summary: '网速慢', suggested_actions: ['检查路由器',], confidence: 0.7}\n```"
    result, errors = parser.parse(broken)
    print(f"  修复后解析: {'✅' if result else '❌'} {result}")

    # 重试修复演示
    print(f"\n  重试修复流程:")
    bad_output = '{"category": "bug"}'  # 缺少必填字段

    def mock_fix(errors, raw, prompt):
        # 模拟 LLM 根据错误修复输出
        return '{"category": "bug", "priority": "high", "summary": "系统崩溃", "suggested_actions": ["重启"]}'

    retry = RetryParser(parser, max_retries=2)
    result, attempts = retry.parse_with_retry(bad_output, mock_fix_fn=mock_fix)
    for a in attempts:
        icon = "✅" if a["success"] else "❌"
        print(f"    第 {a['attempt']} 次: {icon} errors={a['errors'][:2] if a['errors'] else '无'}")
    print(f"    最终结果: {result}")


