# Demo 5: 多格式抽取
# ═══════════════════════════════════════════════════════════

def demo_multi_format():
    print(f"\n\n▶ 5. 多格式抽取")
    print("─" * 60)

    mixed_output = """好的，以下是分析结果：

```json
{"category": "退款", "priority": "high"}
```

<reasoning>用户明确要求退款，属于高优先级</reasoning>

- **处理人**: 李经理
- **预计时间**: 2小时
- **状态**: 待处理"""

    print("  原文:")
    for line in mixed_output.strip().split("\n")[:3]:
        print(f"    {line}")
    print(f"    ...")

    jsons = MultiFormatExtractor.extract_json(mixed_output)
    print(f"\n  JSON 抽取: {jsons}")

    xml = MultiFormatExtractor.extract_xml_tags(mixed_output, "reasoning")
    print(f"  XML 标签: {xml}")

    kv = MultiFormatExtractor.extract_key_value(mixed_output)
    print(f"  Key-Value: {kv}")


