def main():
    print("=== 结构化输出 (Structured Output) ===\n")
    demo_schema()
    demo_json_repair()
    demo_function_calling()
    demo_parsing_retry()
    demo_multi_format()

    print(f"\n\n{'=' * 60}")
    print("📊 结构化输出总结:")
    print(f"""
  技术栈          │ 说明
  ───────────────┼──────────────────────────────────
  JSON Schema     │ 约束输出格式的标准（OpenAI 原生支持）
  Function Call   │ LLM 结构化调工具的底层机制
  Pydantic        │ Python 最强类型校验（pydantic-ai 核心）
  JSON Repair     │ 修复 LLM 常见格式错误（尾逗号/单引号/布尔）
  Retry Parser    │ 解析失败 → 构建修复 prompt → LLM 重试
  多格式抽取       │ 从混合输出中提取 JSON/XML/KV

  框架支持:
  - OpenAI: response_format={"type": "json_schema", ...}
  - pydantic-ai: output_type=MyModel（自动 Schema + 验证）
  - LangChain: PydanticOutputParser / JsonOutputParser
  - Vercel AI SDK: generateObject() + Zod schema
  - Spring AI: BeanOutputConverter<T>""")


if __name__ == "__main__":
    main()
